WITH valid_products AS (SELECT * FROM products WHERE brand = 'Stark'), products_stats AS (SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, MIN(launch_date) min_launch_date FROM valid_products GROUP BY CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT launch_cohort, min_launch_date FROM products_stats ORDER BY min_launch_date DESC, launch_cohort
